sysevent_script_action.script:
//new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', event.parm1, event.parm2);

//MSSOTIQUBE-707 get severity from parm2 instead of hardcode as WARMING, add checking on the severity to ensure it meets alert api requirement
//var severity = 'WARNING';
var text = event.parm1;
//var object = event.parm2;
var par2 = event.parm2;
var pos = par2.indexOf('|');
var object = par2.substring(0, pos);
//Alert Criticality (ALL IN UPPER CASE): "CRITICAL|MAJOR|MINOR|WARNING|INFO"
var severity = par2.substring(pos + 1).toUpperCase();
//set as WARNING in case invalid severity provided
if (severity != 'CRITICAL' && severity != 'MAJOR' && severity != 'MINOR' && severity != 'WARNING' && severity != 'INFO')
	severity='WARNING';


try {

    //Fetch property values for the following - 
    //API End point, key, Client ID, Client Secret and API version required for event creation 
    var itidAPIEndPoint = gs.getProperty('x_hsb11_hsbc_mss_t.hsbc_itid_eventcreation_api');
    var itidAPIKey = gs.getProperty('x_hsb11_hsbc_mss_t.hsbc_itid_eventcreation_key');
    //MSSOTIQUBE-690 Header Auth is used for the new KONG gateway, client id and secret is no longer used
    var itidAPIAuth = gs.getProperty('x_hsb11_hsbc_mss_t.hsbc_itid_eventcreation_header_auth');
    //var itidAPIClientID = gs.getProperty('x_hsb11_hsbc_mss_t.hsbc_itid_eventcreation_client_id');
    //var itidAPIClientSecret = gs.getProperty('x_hsb11_hsbc_mss_t.hsbc_itid_eventcreation_client_secret');
    var itidAPIVersion = gs.getProperty('x_hsb11_hsbc_mss_t.hsbc_itid_eventcreation_apiversion');

    //Convert existing text by reomving all special characters which are not allowed at Event end
    //var textWithoutSpecChars = decodeURIComponent(text);
    //textWithoutSpecChars = text.replace(/[`~%^&|\?;:'"<>\{\}\[\]\\\/]/gi, ' ');

    var textWithoutSpecChars = text.replace(/[`~%^&|\?;:'"<>\{\}\[\]\\\/]/gi, ' ');

    //Check character length, length should not be more than 1024 characters if it is then truncate the text
    if (textWithoutSpecChars.length > 1024)
        textWithoutSpecChars = textWithoutSpecChars.substring(0, 1023);


    //REST call to create event 
    var createNewEvent = new sn_ws.RESTMessageV2('x_hsb11_hsbc_mss_t.HSBC ITID Event API', 'HSBC ITID Event API');
    createNewEvent.setStringParameterNoEscape('version', itidAPIVersion);
    //MSSOTIQUBE-690 Header Auth is used for the new KONG gateway, client id and secret is no longer used
    createNewEvent.setStringParameterNoEscape('itid_api_header_auth', itidAPIAuth);
    //createNewEvent.setStringParameterNoEscape('itid_api_client_id', itidAPIClientID);
    createNewEvent.setStringParameterNoEscape('severity', severity);
    createNewEvent.setStringParameterNoEscape('text', textWithoutSpecChars);
    //createNewEvent.setStringParameterNoEscape('itid_api_client_secret', itidAPIClientSecret);
    createNewEvent.setStringParameterNoEscape('itid_api_key', itidAPIKey);
    createNewEvent.setStringParameterNoEscape('itid_api_type', 'ALERT');
    createNewEvent.setStringParameterNoEscape('object', object);
    createNewEvent.setStringParameterNoEscape('hsbc_itid_event_api', itidAPIEndPoint);
    //createNewEvent.execute();

    var response = createNewEvent.execute();
    var responseBody = response.getBody();
    var httpStatus = response.getStatusCode();

    //MSSOTIQUBE-690 Correct the wordings in logging
    gs.info('Alert API call with severity ' + severity + ' executed with following status ' + httpStatus + ' and the response body is ' + responseBody, 'ITIDEventCreation');

} catch (ex) {
    var message = ex.message;
    //MSSOTIQUBE-690 add logging in catch section
    gs.info('Exception in createITIDEvent (xmatter alert) with error ' + message);
}
